#include <vector>
#include <unordered_map>
#include <algorithm>

class Solution {
public:
    std::vector<int> findXSum(std::vector<int>& nums, int k, int x) {
        int n = nums.size();
        std::vector<int> ans;
        for (int i = 0; i <= n - k; ++i) {
            std::unordered_map<int, int> counts;
            for (int j = i; j < i + k; ++j) counts[nums[j]]++;

            std::vector<std::pair<int, int>> items(counts.begin(), counts.end());
            std::sort(items.begin(), items.end(), [](const auto& a, const auto& b) {
                if (a.second != b.second) return a.second > b.second;
                return a.first > b.first;
            });

            int sum_val = 0;
            int limit = std::min((int)items.size(), x);
            for (int j = 0; j < limit; ++j) {
                sum_val += items[j].first * items[j].second;
            }
            ans.push_back(sum_val);
        }
        return ans;
    }
};

