var findXSum = function(nums, k, x) {
    const n = nums.length;
    const ans = [];

    for (let i = 0; i <= n - k; i++) {
        const counts = new Map();
        for (let j = i; j < i + k; j++) {
            counts.set(nums[j], (counts.get(nums[j]) || 0) + 1);
        }

        const items = Array.from(counts.entries());
        items.sort((a, b) => {
            if (b[1] !== a[1]) return b[1] - a[1];
            return b[0] - a[0];
        });

        let sumVal = 0;
        const limit = Math.min(items.length, x);
        for (let j = 0; j < limit; j++) {
            sumVal += items[j][0] * items[j][1];
        }
        ans.push(sumVal);
    }
    return ans;
};
